module WatchLaterMinClicks (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] video_types [0:15],  // ASCII characters, 16 videos max\n    input wire [4:0] length,              // Number of videos (1-16)\n    output reg [7:0] result,\n    output reg done\n);\n\n    // Parameters\n    localparam [2:0] STATE_IDLE = 3'b000;\n    localparam [2:0] STATE_COUNT_SEGMENTS = 3'b001;\n    localparam [2:0] STATE_FIND_MIN = 3'b010;\n    localparam [2:0] STATE_REMOVE_TYPE = 3'b011;\n    localparam [2:0] STATE_UPDATE_RESULT = 3'b100;\n    localparam [2:0] STATE_DONE = 3'b101;\n\n    // Registers\n    reg [2:0] state;\n    reg [7:0] current_videos [0:15];  // Current remaining videos\n    reg [4:0] remaining_length;\n    reg [7:0] segment_counts [0:7];    // Segment counts for each type (0-7, mapped from ASCII)\n    reg [7:0] min_segments;\n    reg [2:0] selected_type;\n    reg [2:0] type_index;              // Iterating through types\n    reg [4:0] video_index;             // Iterating through videos\n    reg [7:0] temp_result;\n    reg [7:0] last_type;\n    reg counting_done;\n\n    // Helper: Map ASCII to type index (0-7)\n    function automatic [2:0] char_to_type(input [7:0] c);\n        begin\n            char_to_type = c[2:0];  // Use lower 3 bits for type index\n        end\n    endfunction\n\n    // Helper: Check if two types are same\n    function automatic is_same_type(input [7:0] a, input [7:0] b);\n        begin\n            is_same_type = (a == b);\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            remaining_length <= 5'd0;\n            temp_result <= 8'd0;\n            type_index <= 3'd0;\n            video_index <= 5'd0;\n            min_segments <= 8'd255;\n            selected_type <= 3'd0;\n            last_type <= 8'd0;\n            counting_done <= 1'b0;\n            for (integer i = 0; i < 16; i = i + 1) begin\n                current_videos[i] <= 8'd0;\n            end\n            for (integer i = 0; i < 8; i = i + 1) begin\n                segment_counts[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    if (start && length > 0) begin\n                        // Initialize current_videos from input\n                        for (integer i = 0; i < 16; i = i + 1) begin\n                            if (i < length)\n                                current_videos[i] <= video_types[i];\n                            else\n                                current_videos[i] <= 8'hFF;  // Invalid marker\n                        end\n                        remaining_length <= length;\n                        temp_result <= 8'd0;\n                        state <= STATE_COUNT_SEGMENTS;\n                        type_index <= 3'd0;\n                        video_index <= 5'd0;\n                        counting_done <= 1'b0;\n                    end\n                end\n\n                STATE_COUNT_SEGMENTS: begin\n                    // Count segments for current type_index\n                    if (type_index < 8) begin\n                        if (!counting_done) begin\n                            // Reset segment count for this type\n                            segment_counts[type_index] <= 8'd0;\n                            video_index <= 5'd0;\n                            last_type <= 8'hFF;\n                            counting_done <= 1'b1;\n                        end else if (video_index < remaining_length) begin\n                            if (current_videos[video_index] != 8'hFF) begin\n                                if (char_to_type(current_videos[video_index]) == type_index) begin\n                                    // This video is of current type\n                                    if (video_index == 0 || \n                                        last_type == 8'hFF || \n                                        !is_same_type(current_videos[video_index-1], current_videos[video_index])) begin\n                                        // Start of new segment\n                                        segment_counts[type_index] <= segment_counts[type_index] + 1;\n                                    end\n                                    last_type <= current_videos[video_index];\n                                end\n                            end\n                            video_index <= video_index + 1;\n                        end else begin\n                            counting_done <= 1'b0;\n                            type_index <= type_index + 1;\n                        end\n                    end else begin\n                        // Done counting all types\n                        type_index <= 3'd0;\n                        state <= STATE_FIND_MIN;\n                        min_segments <= 8'd255;\n                        selected_type <= 3'd0;\n                    end\n                end\n\n                STATE_FIND_MIN: begin\n                    // Find type with minimum segments (but > 0)\n                    if (type_index < 8) begin\n                        if (segment_counts[type_index] > 0 && segment_counts[type_index] < min_segments) begin\n                            min_segments <= segment_counts[type_index];\n                            selected_type <= type_index;\n                        end\n                        type_index <= type_index + 1;\n                    end else begin\n                        if (min_segments != 8'd255 && remaining_length > 0) begin\n                            // Remove videos of selected_type\n                            video_index <= 5'd0;\n                            state <= STATE_REMOVE_TYPE;\n                        end else begin\n                            // No videos left or all removed\n                            state <= STATE_DONE;\n                        end\n                    end\n                end\n\n                STATE_REMOVE_TYPE: begin\n                    // Remove all videos of selected_type from current_videos\n                    if (video_index < remaining_length) begin\n                        if (current_videos[video_index] != 8'hFF && \n                            char_to_type(current_videos[video_index]) == selected_type) begin\n                            // Remove this video by shifting remaining videos left\n                            for (integer i = video_index; i < remaining_length - 1; i = i + 1) begin\n                                current_videos[i] <= current_videos[i + 1];\n                            end\n                            current_videos[remaining_length - 1] <= 8'hFF;\n                            remaining_length <= remaining_length - 1;\n                            // Stay at same index after shift\n                        end else begin\n                            video_index <= video_index + 1;\n                        end\n                    end else begin\n                        state <= STATE_UPDATE_RESULT;\n                    end\n                end\n\n                STATE_UPDATE_RESULT: begin\n                    temp_result <= temp_result + min_segments;\n                    state <= STATE_COUNT_SEGMENTS;\n                    type_index <= 3'd0;\n                    video_index <= 5'd0;\n                    counting_done <= 1'b0;\n                end\n\n                STATE_DONE: begin\n                    result <= temp_result;\n                    done <= 1'b1;\n                    state <= STATE_IDLE;\n                end\n\n                default: state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule